def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    for c in range(w):
        marker_rows = [r for r in range(h) if g[r][c] == 5]
        if not marker_rows:
            continue

        top = min(marker_rows)
        # Fill blanks above the first marker, using the next colored cell
        # below each blank; the bottom marker acts as a 5-colored endpoint.
        anchors = [(r, g[r][c]) for r in range(top) if g[r][c] != 0]
        anchors.append((top, 5))

        if not anchors:
            continue

        first_r, first_color = anchors[0]
        for r in range(first_r):
            g[r][c] = first_color

        for (r1, color1), (r2, color2) in zip(anchors, anchors[1:]):
            for r in range(r1 + 1, r2):
                if g[r][c] == 0:
                    g[r][c] = color2

        # Extend the marker color down through any empty cells after it.
        for r in range(top + 1, h):
            if g[r][c] == 0:
                g[r][c] = 5

    return g
